'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const cli = path.join(__dirname, 'wordfreq.js');
const fixture = path.join(__dirname, 'sample.txt');

function run(args) {
  return spawnSync(process.execPath, [cli, ...args], {
    cwd: __dirname,
    encoding: 'utf8',
  });
}

function withTempFile(text, callback) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'wordfreq-test-'));
  const file = path.join(dir, 'input.txt');
  try {
    fs.writeFileSync(file, text, 'utf8');
    return callback(file);
  } finally {
    fs.rmSync(dir, { recursive: true, force: true });
  }
}

test('counts words and prints them in descending frequency order', () => {
  const result = run([fixture]);
  assert.equal(result.status, 0, result.stderr);
  assert.equal(result.stderr, '');
  assert.deepEqual(result.stdout.trim().split('\n'), [
    'the 4',
    'cat 3',
    'dog 2',
    'sat 1',
    'on 1',
    'mat 1',
  ]);
});

test('normalizes words to lowercase', () => {
  withTempFile('Apple apple APPLE Banana BANANA', (file) => {
    const result = run([file]);
    assert.equal(result.status, 0, result.stderr);
    assert.deepEqual(result.stdout.trim().split('\n'), ['apple 3', 'banana 2']);
  });
});

test('orders equal-frequency words alphabetically for deterministic ties', () => {
  withTempFile('pear plum peach', (file) => {
    const result = run([file]);
    assert.equal(result.status, 0, result.stderr);
    assert.deepEqual(result.stdout.trim().split('\n'), ['peach 1', 'pear 1', 'plum 1']);
  });
});

test('limits output to the requested top N words', () => {
  withTempFile('red blue blue green green green yellow yellow yellow yellow', (file) => {
    const result = run([file, '2']);
    assert.equal(result.status, 0, result.stderr);
    assert.deepEqual(result.stdout.trim().split('\n'), ['yellow 4', 'green 3']);
  });
});

test('rejects a missing file argument', () => {
  const result = run([]);
  assert.notEqual(result.status, 0);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, /usage|file|argument/i);
});

test('rejects an invalid top-N argument', () => {
  withTempFile('one two', (file) => {
    const result = run([file, 'nope']);
    assert.notEqual(result.status, 0);
    assert.equal(result.stdout, '');
    assert.match(result.stderr, /usage|positive|integer|number|N/i);
  });
});

test('reports a file that does not exist', () => {
  const missing = path.join(os.tmpdir(), `wordfreq-no-such-file-${process.pid}.txt`);
  const result = run([missing]);
  assert.notEqual(result.status, 0);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, /no such file|not found|enoent|cannot|error/i);
});

