'use strict';

const fs = require('node:fs');

/**
 * Return the n most frequent words in text, ordered by descending frequency
 * and then alphabetically for deterministic ties. Words are lowercased and
 * consist of Unicode letters and numbers, optionally joined by apostrophes.
 * @param {string} text
 * @param {number} n
 * @returns {Array<{word: string, count: number}>}
 */
function topWords(text, n) {
  if (typeof text !== 'string') {
    throw new TypeError('text must be a string');
  }
  if (!Number.isSafeInteger(n) || n <= 0) {
    throw new RangeError('n must be a positive safe integer');
  }

  const counts = new Map();
  const tokens = text.toLocaleLowerCase().match(/[\p{L}\p{N}]+(?:['’][\p{L}\p{N}]+)*/gu) || [];
  for (const word of tokens) {
    counts.set(word, (counts.get(word) || 0) + 1);
  }

  return Array.from(counts, ([word, count]) => ({ word, count }))
    .sort((a, b) => b.count - a.count || (a.word < b.word ? -1 : a.word > b.word ? 1 : 0))
    .slice(0, n);
}

function usage() {
  return 'Usage: node wordfreq.js <file> [N]';
}

function main(args) {
  if (args.length < 1 || args.length > 2) {
    console.error(usage());
    return 2;
  }

  const file = args[0];
  let n = 10;
  if (args.length === 2) {
    if (!/^[0-9]+$/.test(args[1])) {
      console.error('Error: N must be a positive integer.');
      console.error(usage());
      return 2;
    }
    n = Number(args[1]);
    if (!Number.isSafeInteger(n) || n <= 0) {
      console.error('Error: N must be a positive safe integer.');
      return 2;
    }
  }

  let text;
  try {
    text = fs.readFileSync(file, 'utf8');
  } catch (error) {
    console.error(`Error: cannot read file "${file}": ${error.message}`);
    return 1;
  }

  for (const { word, count } of topWords(text, n)) {
    console.log(`${word}\t${count}`);
  }
  return 0;
}

module.exports = { topWords };

if (require.main === module) {
  process.exitCode = main(process.argv.slice(2));
}

